{"command": "cd /work/output && cat > probe.py <<'EOF'
import time, json, numpy as np
from gri_bench.api import load_instance, Experiment, PARAMETERS
inst=load_instance(); ex=Experiment(inst)
rng=np.random.default_rng(7)
def mk(x):
    return {'mode':'responsive','parameters':dict(zip(PARAMETERS,x))}
def score(m):
    pen=0.
    if m['max_trajectory_tbr70']>0: pen+=2.0*max(0,m['max_trajectory_tbr70']-0.5)
    if m['max_trajectory_tbr54']>0: pen+=5.0*m['max_trajectory_tbr54']
    if m['minimum_glucose']<80: pen+=0.5*(80-m['minimum_glucose'])
    return m['mean_tir']-pen
t0=time.time(); res=[]
for i in range(48):
    x=np.array([np.exp(rng.uniform(np.log(1e-4),np.log(4e-3))),
                rng.uniform(0.51,3.0), rng.uniform(80,320), rng.uniform(0.6,4.0),
                np.exp(rng.uniform(np.log(2),np.log(20))), rng.uniform(1.0,4.0)])
    m=ex.evaluate(mk(x)); s=score(m)
    res.append((s,list(x),{k:round(m[k],1) for k in ('mean_tir','max_trajectory_tbr70','max_trajectory_tbr54','minimum_glucose')}))
res.sort(key=lambda r:-r[0])
for r in res[:10]: print(round(r[0],1),[round(v,5) for v in r[1]],r[2])
print('elapsed',time.time()-t0)
